def tb(rows,head=None):
    h='<table>'
    if head:h+='<tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr>'
    return h+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</table>'
NOTES=[
['obs','Observation tools','<p><b>On the ground:</b> ASOS (automated airport stations), mesonets (dense local stations), buoys (water). <b>Aloft:</b> radiosondes on balloons, aircraft reports.</p>'+tb([['Reflectivity','How much precipitation, and where'],['Base velocity','Motion toward or away from the radar'],['Correlation coefficient (CC)','How alike the targets are. Rain is high. Debris is low'],['Storm relative motion','Winds with the storm\'s own movement removed. Shows rotation'],['Composite reflectivity','Strongest echo at any height'],['Wind profile','Winds at each height over the radar']],['Radar product','Shows'])+'<p><b>Satellite:</b> visible needs daylight. Infrared (IR) works day and night: cold cloud tops are bright, so tall storms stand out. Water vapor shows moisture in the middle and upper air.</p><div class="trap">Velocity: toward the radar is NEGATIVE (green). Away is POSITIVE (red). Think "red = run away".</div>'],
['maps','Station models and METAR','<p>A station model packs temperature, dew point, pressure, wind and sky cover into one symbol.</p>'+tb([['Upper left','Temperature'],['Lower left','Dew point'],['Upper right','Pressure, last 3 digits (tenths of mb)'],['Lower right','3-hour pressure change'],['Center circle','Sky cover (more filled = cloudier)'],['Barb staff','Points toward where wind COMES FROM'],['Half flag / full / pennant','5 kt / 10 kt / 50 kt']],['Spot','Means'])+'<div class="card key"><span class="f">Pressure: 500 or more → put 9 in front.  Less than 500 → put 10.</span><span class="f">132 → 1013.2 mb   987 → 998.7 mb   047 → 1004.7 mb</span></div><p><b>METAR</b> example: <code>KOKC 202153Z 18018G28KT 6SM TSRA BKN040CB 27/22 A2985</code></p>'+tb([['KOKC','Station'],['202153Z','Day 20, 21:53 UTC'],['18018G28KT','From 180° at 18 kt, gusts 28 kt'],['6SM','Visibility 6 statute miles'],['TSRA','Thunderstorm with rain'],['BKN040CB','Broken clouds at 4,000 ft, cumulonimbus'],['27/22','Temp 27°C, dew point 22°C'],['A2985','Altimeter 29.85 inHg']],['Part','Meaning'])+'<p>Sky: FEW 1–2/8, SCT 3–4/8, BKN 5–7/8, OVC 8/8. Height × 100 ft. Negative temps start with M (M05 = −5°C).</p>'],
['upper','Upper air, soundings, LCL, CAPE','<p><b>Standard levels:</b> 850 mb (low moisture), 700 mb (steering), 500 mb (troughs and ridges), 300 mb (jet stream).</p><p><b>Hodograph:</b> plots the wind at each height as a point, then connects them. A long, curving path means strong shear. Curving clockwise with height (veering) favors supercells.</p><p><b>Stüve / Skew-T:</b> temperature (solid) and dew point (dashed) against pressure. Lines close together = moist or cloudy. Far apart = dry. A layer where temperature rises with height is an <b>inversion</b> (very stable, a "cap").</p><p><b>States/Nationals:</b></p><div class="card key"><span class="f">LCL (m) ≈ 125 × (T − Td in °C)</span><span class="f">Dry parcel cools 10 °C per km. Typical air cools about 6.5 °C per km.</span></div>'+tb([['Under 1,000','Marginal'],['1,000–2,500','Moderate'],['2,500–4,000','Strong'],['Over 4,000','Extreme']],['CAPE (J/kg)','Instability'])+'<div class="trap">Low LCL (low cloud base) raises tornado risk. CAPE alone is not enough: you also need shear and a lift trigger.</div>'],
['setup','Setup for severe weather','<p><b>Recipe:</b> moisture + instability + lift + wind shear.</p>'+tb([['Jet stream','Steers storms, adds energy aloft'],['Cold front','Cold air pushes in. Fast, sharp storms'],['Warm front','Warm air slides over cold. Wide, steady precipitation'],['Stationary','Stalled boundary'],['Occluded','Cold front catches warm front'],['Dryline','Moisture boundary (moist east, dry west on the Plains). Not a temperature boundary'],['Atmospheric river','Narrow stream of heavy water vapor. Extreme rain at landfall'],['Wind shear','Wind changes with height. Organizes storms; directional shear starts rotation'],['Fetch','Distance wind blows over water'],['Ocean heat content','Warm deep water fuels hurricanes. Storm wakes are cooler']],['Ingredient','Role'])+'<p>Mountains lift air (trigger storms), and can block, weaken or redirect storms.</p>'],
['clouds','Severe-weather clouds',tb([['Cumulonimbus','The thunderstorm cloud'],['Wall cloud','Lowered, often rotating base under the updraft. Tornado warning sign'],['Shelf cloud','Wedge at the leading edge. Marks the gust front'],['Funnel cloud','Rotating cone not touching ground'],['Mammatus','Pouches under an anvil. Often a storm weakening']],['Cloud','Signal'])+'<div class="trap">Funnel cloud = not on the ground. Once it touches down it is a tornado.</div>'],
['dh','Drought and heat waves','<p><b>Drought:</b> long stretch with too little precipitation. <b>Heat wave:</b> long stretch of abnormal heat. Both are often caused by a <b>blocking high-pressure ridge</b> that sits in place and steers storms away.</p><p>Effects: crop loss, water limits, wildfire, heat illness, power demand.</p>'],
['precip','Precipitation, flooding, IDF','<p><b>How it forms:</b></p>'+tb([['Collision-coalescence','Drops merge into bigger drops (warm clouds)'],['Bergeron process','Ice crystals grow while supercooled drops shrink (cold clouds)'],['Riming','Supercooled drops freeze onto ice (builds graupel and hail)'],['Aggregation','Ice crystals stick together (snowflakes)']],['Process','Result'])+tb([['Snow','Cold all the way down'],['Sleet','Snow melts, then refreezes as ice pellets in a cold layer near the ground'],['Freezing rain','Rain falls on a surface below 0 °C and freezes on contact'],['Hail','Strong updraft keeps stones aloft, they grow by riming'],['Rain','Warm all the way down']],['Type','Layers it fell through'])+'<p><b>Flood types:</b> flash (minutes to hours), stream/river (rises over days), urban (drains overwhelmed). Burn scars and steep land produce debris flows and mudslides.</p><p><b>Hail:</b> pea ¼ in, penny ¾ in, quarter 1 in (severe), golf ball 1¾ in, baseball 2¾ in.</p><p><b>States/Nationals:</b> an IDF curve shows rainfall intensity versus duration for a return period. Longer duration = lower intensity. Rarer storms (100-yr) plot higher. Chance in any year = 1 ÷ return period.</p>'],
['light','Lightning','<p>Ice and graupel collide in the cloud. Smaller, lighter ice rises with positive charge. Heavier graupel falls with negative charge. The cloud base is mostly negative. The ground below turns positive.</p>'+tb([['Cloud-to-ground','Cloud to the surface'],['Intracloud','Inside one cloud'],['Cloud-to-cloud','Between two clouds'],['Cloud-to-air','Cloud into clear air']],['Type','Path'])+'<p><b>Lightning detection systems</b> locate strikes using sensors across a network (they time the signal at each sensor).</p><div class="card key"><span class="f">Miles = seconds between flash and thunder ÷ 5</span></div>'],
['tstorm','Severe thunderstorms','<p>NWS "severe": hail ≥ 1 inch, wind ≥ 58 mph, or a tornado.</p>'+tb([['Single-cell','One short-lived cell'],['Multicell','Cluster or line at different stages'],['Supercell','One long-lived storm with a rotating updraft (mesocyclone). Makes the strongest tornadoes'],['MCC','Large round long-lived cluster']],['Type','Key trait'])+'<p><b>Life cycle:</b> cumulus (updraft only) → mature (updraft + downdraft, worst weather) → dissipating (downdraft only).</p>'],
['winds','Winds from storms','<p><b>Straight-line winds</b> = damage not from rotation. Damage is spread out in one direction.</p>'+tb([['Downdraft','Sinking air'],['Downburst','Downdraft that hits the ground and spreads out'],['Microburst','Downburst under 4 km wide. Brief, intense'],['Macroburst','Downburst 4 km or wider. Longer lasting'],['Gust front','Leading edge of cool outflow'],['Squall line','Organized line of storms'],['Derecho','Long-lived, widespread windstorm. Track of hundreds of miles'],['Downslope wind','Air accelerating down a mountain slope']],['Term','Meaning'])+'<p><b>On radar:</b> bow echo (derecho/damaging wind), fine line (gust front), bowing segment on a squall line.</p>'],
['torn','Tornadoes, scales, radar','<p>Tornado = violently rotating column touching the ground and a cloud base. Waterspout = same over water. Peak: late afternoon, spring, Plains and Southeast.</p>'+tb([['EF0','65–85 mph'],['EF1','86–110 mph'],['EF2','111–135 mph'],['EF3','136–165 mph'],['EF4','166–200 mph'],['EF5','over 200 mph']],['EF scale','3-second gust'])+'<div class="trap">F scale = before 1 Feb 2007. EF scale = on or after. Both rate DAMAGE, not measured wind.</div>'+tb([['Hook echo','Rain/debris wrapping a mesocyclone (reflectivity)'],['TVS','Tight inbound-outbound velocity pair = intense rotation'],['Debris ball','Low CC inside the hook = debris in the air'],['Bow echo','Straight-line wind; may hide small tornadoes']],['Signature','Means'])],
['hurr','Hurricanes','<p>Hurricane = typhoon = cyclone (same storm, different ocean). Needs warm water (about 26.5 °C or more), moisture, low shear, and distance from the equator.</p><p><b>Life cycle:</b> Invest → Depression (under 39 mph) → Tropical Storm (39–73) → Hurricane (74+) → Major (Cat 3+).</p>'+tb([['Cat 1','74–95 mph'],['Cat 2','96–110 mph'],['Cat 3','111–129 mph (major)'],['Cat 4','130–156 mph (major)'],['Cat 5','157+ mph (major)']],['Saffir-Simpson','Sustained wind'])+'<p><b>Parts:</b> eye (calm, 20–40 mi), eyewall (worst winds and rain), spiral bands (can spawn tornadoes).</p><p><b>Storm surge</b> = water pushed onshore. Biggest with strong wind, large size, slow movement, and shallow, funnel-shaped coasts. Often the deadliest hazard.</p><p>Land cuts off the heat source, so storms weaken. Shear and dry air weaken them. El Niño tends to raise shear in the Atlantic and quiet it.</p><p>Atlantic season: June 1 – Nov 30.</p>'],
['winter','Severe winter storms',tb([['Blizzard','Wind or gusts ≥ 35 mph + falling/blowing snow + visibility under ¼ mile, all for 3+ hours'],['Nor\'easter','Strong East Coast storm; northeast winds; snow, coastal flooding, wind'],['Lake effect','Cold air over warm open lake water, narrow heavy snow bands downwind'],['Ice storm','Freezing rain builds up ice. ¼ inch can bring down lines']],['Storm','Key facts'])+'<div class="trap">A blizzard does not need new snow. Wind can blow old snow.</div>'],
['safety','Hazards and safety',tb([['Tornado','Violent wind, debris'],['Hurricane','Storm surge, wind, inland flooding'],['Severe thunderstorm','Hail, wind, lightning'],['Flash flood','Rapid water rise'],['Lightning','Direct strike, fires'],['Winter storm','Snow/ice load, low visibility, cold'],['Drought/heat','Water shortage, heat illness']],['Storm','Main hazard'])+tb([['Watch','Conditions favorable. Get ready'],['Warning','Happening or about to. Act now'],['Advisory','Less serious but still disruptive']],['Alert','Means'])+'<p><b>Actions:</b> tornado = lowest floor, interior room, no windows. Hurricane = follow evacuation orders. Flash flood = go high, never drive through water. Lightning = indoors or hard-topped car. Generators outside only (carbon monoxide).</p><p><b>Reliable sources:</b> weather.gov, spc.noaa.gov (storms), nhc.noaa.gov (tropics).</p>'],
['cases','Historic events and case analysis',tb([['Galveston 1900','Hurricane, huge storm surge, deadliest US natural disaster'],['Andrew 1992','Hurricane, small and intense, south Florida'],['Katrina 2005','Hurricane, surge and levee failures, Gulf Coast'],['Sandy 2012','Hurricane turned post-tropical, giant size, surge in NY/NJ'],['Ida 2021','Hurricane, Louisiana landfall, then remnant flash flooding in the Northeast'],['Ian 2022','Hurricane, southwest Florida, large surge'],['Hilary 2023','Pacific hurricane, rare Southern California tropical storm rain'],['Helene 2024','Hurricane, Florida Big Bend, deadly inland flooding in the Appalachians'],['Erin 2025','Atlantic hurricane that intensified rapidly to a major hurricane'],['Melissa 2025','Very intense hurricane that hit Jamaica'],['Blizzard of March 1888','East Coast blizzard'],['Dust Bowl 1930s','Drought, plowed soil, dust storms on the Plains'],['Xenia 1974','Violent tornado in an outbreak (Ohio)'],['April 2011','Largest tornado outbreak in the Southeast'],['Great Flood 1993','Mississippi/Missouri river flooding after months of rain'],['Storm of the Century 1993','Huge March storm: blizzard, tornadoes, surge']],['Event','Know the type'])+'<p>You will get data. <b>Case method:</b> 1) name the storm type, 2) list the clues, 3) apply the scale or signature, 4) check dates (EF cutoff 1 Feb 2007).</p>']]
C={}
C['obs']=[['Ground tools','ASOS = automated airport stations. Mesonets = dense local stations. Buoys = water. Radiosondes = balloon packs that profile the air above.'],['Reflectivity','Shows how much rain or hail and where. Stronger echoes look hotter or darker. Composite shows the strongest echo at any height.'],['Velocity','Shows motion toward or away from the radar. Toward is green (negative). Away is red (positive).'],['Correlation coefficient','Tells how alike the targets are. Rain is high. Debris is low. A low spot in a hook echo can mean a tornado is lofting debris.'],['Storm relative motion','Takes out the storm\'s own movement. Rotation is easier to see.'],['Satellite','Visible needs daylight. Infrared and water vapor work at night. Cold tops show bright on IR, so tall storms stand out.']]
C['maps']=[['Station model','Temperature upper left. Dew point lower left. Pressure upper right. Pressure change lower right. Sky cover is the circle. Wind barb is the staff.'],['Wind barb','The staff points to where wind comes FROM. Half flag 5 kt. Full flag 10. Triangle 50. Add them up.'],['Pressure code','Take the three digits. 500 or more? Put 9 in front. Less than 500? Put 10. Add a decimal before the last digit.','132 → 1013.2 mb'],['METAR wind','18018G28KT means from 180°, 18 knots, gusting 28.'],['METAR sky','FEW, SCT, BKN, OVC get cloudier. The three digits are height in hundreds of feet. BKN040 = 4,000 ft.'],['METAR temps','27/22 means 27 °C and dew point 22 °C. An M means minus.'],['Altimeter','A2985 = 29.85 inches of mercury.']]
C['upper']=[['Pressure levels','850 mb = low moisture. 700 mb = steering. 500 mb = troughs and ridges. 300 mb = jet stream.'],['Hodograph','A plot of wind at each height. A long curved path means strong shear. Clockwise turning with height helps supercells.'],['Sounding','Temperature solid. Dew point dashed. Lines close = moist or cloudy. Far apart = dry.'],['Inversion','A layer where temperature rises with height. Very stable. It can act as a cap that holds storms back.'],['Skew-T','Same skills as Stüve. The lines are just tilted to spread them out. (States/Nationals)'],['LCL','Height where a rising parcel makes cloud. Lower LCL means lower cloud base and higher tornado risk.','LCL m ≈ 125 × (T − Td)'],['CAPE','Storm fuel in J/kg. Under 1000 marginal. 1000–2500 moderate. 2500–4000 strong. Over 4000 extreme.']]
C['setup']=[['The recipe','Moisture, instability, lift, and shear. Miss one and storms struggle.'],['Jet stream','Fast river of air aloft. It steers storms and adds energy.'],['Fronts','Cold front: fast and sharp storms. Warm front: wide steady rain. Occluded: cold catches warm. Stationary: stalled.'],['Dryline','Boundary between moist and dry air. It is about moisture, not temperature. Common on the Plains.'],['Wind shear','Wind changing with height. It lets updraft and downdraft work apart. Direction change starts rotation.'],['Atmospheric river','A narrow stream of heavy water vapor. Can drop extreme rain at landfall.'],['Water and land','Long fetch and warm water give storms energy. Storms leave a cooler wake. Mountains can trigger, weaken, or redirect storms.']]
C['clouds']=[['Cumulonimbus','The thunderstorm cloud. It can bring every type of severe weather.'],['Wall cloud','A lowered, often rotating base under the main updraft. A key tornado warning sign.'],['Shelf cloud','A wedge along the leading edge. It marks the gust front.'],['Funnel cloud','Rotating cone from the storm base. Not on the ground yet.'],['Mammatus','Pouches under an anvil. Often seen as a storm weakens.']]
C['dh']=[['Drought','A long period with far too little precipitation. Water runs short.'],['Heat wave','A long period of unusually high temperatures.'],['Common cause','A blocking high-pressure ridge. It parks over a region and pushes storms away.'],['Effects','Crop loss, water limits, wildfire risk, and heat illness.']]
C['precip']=[['Warm rain','Collision-coalescence: small drops bump and merge into raindrops.'],['Cold clouds','Bergeron process: ice crystals grow while supercooled droplets shrink.'],['Riming and aggregation','Riming: drops freeze onto ice, making graupel and hail. Aggregation: ice crystals stick to make snowflakes.'],['Layers decide','Snow: cold all the way. Sleet: refreezes in a cold layer near the ground. Freezing rain: falls as liquid, freezes on contact.'],['Hail size','Pea ¼ in. Penny ¾. Quarter 1 in (severe). Golf ball 1¾. Baseball 2¾. Bigger means stronger updraft.'],['Floods','Flash: minutes to hours. River: days. Urban: drains overwhelmed. Heavy rain on burn scars makes debris flows.'],['IDF curves','Intensity versus duration. Short bursts are more intense. Rarer storms plot higher. Chance per year = 1 ÷ return period.']]
C['light']=[['How clouds charge','Ice and graupel collide. Light ice rises (positive). Heavy graupel falls (negative). The base ends up mostly negative.'],['Four types','Cloud-to-ground. Intracloud. Cloud-to-cloud. Cloud-to-air.'],['Counting','Seconds from flash to thunder ÷ 5 = miles away.','15 s ÷ 5 = 3 mi'],['Detection','Networks of sensors time the signal to find each strike.']]
C['tstorm']=[['Severe means','Hail 1 inch or bigger, wind 58 mph or more, or a tornado.'],['Single-cell','One short-lived storm.'],['Multicell','A cluster or line. New cells keep forming.'],['Supercell','One long-lived storm with a rotating updraft called a mesocyclone. Makes the strongest tornadoes.'],['MCC','A big, round, long-lived cluster of storms.'],['Life cycle','Cumulus: updraft only. Mature: updraft and downdraft, worst weather. Dissipating: downdraft only.']]
C['winds']=[['Straight-line wind','Any storm wind damage that is not from rotation. The most common wind report.'],['Downburst','A downdraft that hits the ground and spreads out.'],['Micro or macro','Microburst: under 4 km wide. Macroburst: 4 km or more.'],['Gust front','The leading edge of cool outflow. It can show as a shelf cloud.'],['Squall line and derecho','Squall line: organized line of storms. Derecho: long-lived windstorm with hundreds of miles of damage.'],['Downslope wind','Air speeds up as it sinks down a mountain. No thunderstorm needed.'],['On radar','Bow echo = derecho or damaging wind. Fine line = gust front. Bowing segment = strongest wind on a squall line.']]
C['torn']=[['Tornado','A violently rotating column touching the ground and a cloud. A waterspout is the same thing over water.'],['When and where','Late afternoon, spring, Plains and Southeast. But it can happen any time.'],['EF scale','EF0 65–85. EF1 86–110. EF2 111–135. EF3 136–165. EF4 166–200. EF5 over 200 mph.'],['Which scale?','Before 1 Feb 2007: Fujita (F). On or after: Enhanced Fujita (EF). Both rate damage.'],['Hook echo','A reflectivity hook wrapping around the mesocyclone.'],['TVS','Strong inbound and outbound velocity side by side. Intense rotation.'],['Debris ball','Low correlation coefficient inside the hook. Debris is in the air.']]
C['hurr']=[['Same storm','Hurricane, typhoon, and cyclone are one storm type named by ocean.'],['Life cycle','Invest, depression, tropical storm (39–73 mph), hurricane (74+), major hurricane (Cat 3+).'],['Saffir-Simpson','Cat 1: 74–95. Cat 2: 96–110. Cat 3: 111–129. Cat 4: 130–156. Cat 5: 157+ mph.'],['Needs','Warm water (26.5 °C+), moisture, low shear, away from the equator.'],['Structure','Eye: calm. Eyewall: worst wind and rain. Spiral bands: showers, tornadoes.'],['Storm surge','Water pushed onshore. Bigger with strong, large, slow storms and shallow coasts. Often the deadliest hazard.'],['Weakening','Land, wind shear, dry air, and cooler water all weaken a storm.']]
C['winter']=[['Blizzard','Wind or gusts of 35 mph or more, snow in the air, and visibility under ¼ mile. All for at least 3 hours.'],['No new snow needed','Wind blowing old snow can meet the blizzard test.'],['Nor\'easter','Big East Coast storm. Northeast winds. Snow, wind, and coastal flooding.'],['Lake effect','Cold air over warm open lake water makes narrow heavy snow bands downwind.'],['Ice storm','Freezing rain coats everything. ¼ inch can break lines and branches.']]
C['safety']=[['Watch','Conditions favorable. Get ready.'],['Warning','Happening or about to. Act now.'],['Advisory','Less serious but still disruptive.'],['Tornado','Lowest floor, interior room, away from windows.'],['Hurricane and surge','Follow evacuation orders. Surge is often the deadliest part.'],['Flood and lightning','Flood: go high, never drive through water. Lightning: get indoors or into a hard-topped car.'],['Good sources','weather.gov, spc.noaa.gov for storms, nhc.noaa.gov for tropics.'],['After the storm','Use generators outside. Stay away from downed lines. Power loss can cause carbon monoxide danger.']]
C['cases']=[['Hurricane list','Galveston 1900, Andrew 1992, Katrina 2005, Sandy 2012, Ida 2021, Ian 2022, Hilary 2023, Helene 2024, Erin 2025, Melissa 2025.'],['Non-hurricane list','Blizzard of March 1888. Dust Bowl 1930s. Xenia tornado 1974. April 2011 outbreaks. Great Flood 1993. Storm of the Century 1993.'],['You will not memorize','The rules say you analyze data given. Know what type each event was.'],['Case method','1) Name the storm type. 2) List the clues. 3) Use the right scale or signature. 4) Check the date against cutoffs.'],['Dust Bowl','Long drought plus plowed soil gave huge dust storms on the Plains.'],['Great Flood 1993','Months of heavy rain flooded the Mississippi and Missouri rivers.']]
GL=[['mesonet','A dense local network of weather stations.'],['radiosonde','A balloon instrument package that measures the air above.'],['reflectivity','Radar measure of how much is falling.'],['correlation coefficient','Radar measure of how alike targets are. Low means debris or mixed targets.'],['hodograph','A plot of wind speed and direction at each height.'],['inversion','A layer where temperature rises with height.'],['LCL','Lifting condensation level: height where a rising parcel becomes cloud.'],['CAPE','Convective available potential energy: storm fuel.'],['dryline','A boundary between moist and dry air.'],['atmospheric river','A narrow stream of heavy water vapor.'],['fetch','The distance wind blows over open water.'],['mesocyclone','A rotating updraft inside a supercell.'],['derecho','A long-lived, widespread straight-line windstorm.'],['storm surge','Ocean water pushed onshore by a storm.'],['return period','Average time between storms of a given strength.'],['supercooled','Liquid water colder than 0 °C.']]
STUCK=['Write down what you KNOW and what the question wants.','Find the figure or number clue. Read the labels and units.','Match it to a rule, scale, or signature. Check the sizes sound sensible.']
